DROP DATABASE IF EXISTS soundwave_live;
CREATE DATABASE soundwave_live CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE soundwave_live;

CREATE TABLE ticket_sale_wide (
